#!/usr/bin/perl
use strict;
use warnings;
use File::Find;

my $root = '/bench/repo';

# Parse go files to extract package name and functions
sub parse_go_file {
    my ($path, $is_decl) = @_;
    open my $fh, '<', $path or return;
    my @lines = <$fh>;
    close $fh;

    my $pkg = '';
    for (@lines) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    return unless $pkg;

    my @funcs;
    my $i = 0;
    while ($i <= $#lines) {
        my $line = $lines[$i];
        if ($line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
            my $name = $1;
            push @funcs, { name => $name, pkg => $pkg, path => $path, line => $i+1 };
        }
        $i++;
    }
    return @funcs;
}

# Collect all declarations in internal/
my @decls;
find(sub {
    return unless /\.go$/;
    return if /_test\.go$/;
    return unless $File::Find::name =~ m{^$root/internal/};
    push @decls, parse_go_file($File::Find::name, 1);
}, $root);

# Read all go source (non-test for call counting? include tests as callers too)
my @all_go;
find(sub {
    return unless /\.go$/;
    push @all_go, $File::Find::name;
}, $root);

my %file_content;
for my $f (@all_go) {
    open my $fh, '<', $f or next;
    local $/;
    $file_content{$f} = <$fh>;
    close $fh;
}

# Build package -> directory mapping for internal decls
my %pkg_dirs;
for my $d (@decls) {
    my ($dir) = ($d->{path} =~ /^(.*)\/[^\/]+$/);
    $pkg_dirs{$d->{pkg}}{$dir} = 1;
}

# For each decl, count callers
my %fanin;
for my $d (@decls) {
    my $name = $d->{name};
    my $pkg = $d->{pkg};
    my $decl_path = $d->{path};
    my ($decl_dir) = ($decl_path =~ /^(.*)\/[^\/]+$/);

    my %callers; # file:line of call sites

    for my $f (@all_go) {
        my $content = $file_content{$f};
        my @lines = split /\n/, $content;

        # Get package of caller file
        my $caller_pkg = '';
        for (@lines) {
            if (/^package\s+(\w+)/) { $caller_pkg = $1; last; }
        }

        for my $ln (0..$#lines) {
            my $line = $lines[$ln];
            next if $ln+1 == $d->{line} && $f eq $decl_path && $line =~ /^func\s+/;

            # Exported cross-package: pkg.FuncName(
            if ($name =~ /^[A-Z]/) {
                if ($line =~ /\b\Q$pkg\E\.\Q$name\E\s*\(/) {
                    $callers{"$f:$ln"} = 1;
                    next;
                }
            }

            # Same package unqualified call
            if ($caller_pkg eq $pkg) {
                # Same directory check - go same package must be same dir
                my ($caller_dir) = ($f =~ /^(.*)\/[^\/]+$/);
                if ($caller_dir eq $decl_dir || 1) { # same pkg name
                    if ($line =~ /\b\Q$name\E\s*\(/ && $line !~ /^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/) {
                        $callers{"$f:$ln"} = 1;
                    }
                }
            }

            # Method calls: .MethodName(
            if ($line =~ /\.\Q$name\E\s*\(/ && $line !~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/) {
                # Could be method - count if decl is a method (has receiver in original)
                # Re-check decl
                open my $dfh, '<', $decl_path or next;
                my @dlines = <$dfh>;
                close $dfh;
                my $decl_line = $dlines[$d->{line}-1] // '';
                if ($decl_line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/) {
                    $callers{"$f:$ln"} = 1;
                }
            }
        }
    }

    my $count = scalar keys %callers;
    my $symbol = ($name =~ /^[A-Z]/) ? "$pkg.$name" : "$pkg.$name";
    $fanin{"$symbol|$decl_path"} = $count;
}

# Sort by fanin
my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;
for my $k (@sorted[0..19]) {
    my ($sym, $path) = split /\|/, $k, 2;
    print "$fanin{$k}\t$sym\t$path\n";
}
