#!/usr/bin/perl
use strict;
use warnings;

my $root = '/bench/repo';

sub parse_go_file {
    my ($path) = @_;
    open my $fh, '<', $path or return;
    my @lines = <$fh>;
    close $fh;
    my $pkg = '';
    for (@lines) {
        if (/^package\s+(\w+)/) { $pkg = $1; last; }
    }
    return unless $pkg;
    my @funcs;
    for my $i (0..$#lines) {
        if ($lines[$i] =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
            push @funcs, { name => $1, pkg => $pkg, path => $path, line => $i+1, is_method => ($lines[$i] =~ /^func\s+\(/ ? 1 : 0) };
        }
    }
    return @funcs;
}

my @decls;
my @all_go;
open my $find, '-|', "find", $root, '-name', '*.go', '-type', 'f' or die $!;
while (<$find>) {
    chomp;
    push @all_go, $_;
    if (/\/internal\// && !/_test\.go$/) {
        push @decls, parse_go_file($_);
    }
}
close $find;

my %file_content;
for my $f (@all_go) {
    open my $fh, '<', $f or next;
    local $/; $file_content{$f} = <$fh>; close $fh;
}

my %fanin;
for my $d (@decls) {
    my ($name, $pkg, $decl_path, $decl_line, $is_method) = @$d{qw/name pkg path line is_method/};
    my ($decl_dir) = ($decl_path =~ /^(.*)\/[^\/]+$/);
    my %callers;

    for my $f (@all_go) {
        my @lines = split /\n/, $file_content{$f};
        my $caller_pkg = '';
        for (@lines) { if (/^package\s+(\w+)/) { $caller_pkg = $1; last; } }
        my ($caller_dir) = ($f =~ /^(.*)\/[^\/]+$/);

        for my $ln (0..$#lines) {
            my $line = $lines[$ln];
            next if $f eq $decl_path && $ln+1 == $decl_line;

            my $matched = 0;
            if ($name =~ /^[A-Z]/) {
                $matched = 1 if $line =~ /\b\Q$pkg\E\.\Q$name\E\s*\(/;
            }
            if (!$matched && $caller_pkg eq $pkg && $caller_dir eq $decl_dir) {
                $matched = 1 if $line =~ /\b\Q$name\E\s*\(/ && $line !~ /^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/;
            }
            if (!$matched && $is_method) {
                $matched = 1 if $line =~ /\.\Q$name\E\s*\(/;
            }
            $callers{"$f:$ln"} = 1 if $matched;
        }
    }
    my $sym = "$pkg.$name";
    $fanin{"$sym|$decl_path"} = scalar keys %callers;
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;
for my $k (@sorted[0..29]) {
    my ($sym, $path) = split /\|/, $k, 2;
    print "$fanin{$k}\t$sym\t$path\n";
}
