        next if $is_method && $skip{$name};
        my $recv_type = '';
        if ($recv =~ /\*?(\w+)/) { $recv_type = $1; }
        push @decls, { pkg=>$pkg, name=>$name, path=>$f, line=>$i+1, is_method=>$is_method, exported=>($name=~/^[A-Z]/), recv_type=>$recv_type };
